import { Directory, File, Paths } from "expo-file-system";
import { createId, type ChatAttachment, type ChatAttachmentKind } from "./types";

export const MAX_COMPOSER_ATTACHMENTS = 4;
export const MAX_BINARY_ATTACHMENT_BYTES = 8 * 1024 * 1024;
export const MAX_TEXT_ATTACHMENT_BYTES = 1 * 1024 * 1024;

const TEXT_EXTENSIONS = new Set([
  "txt", "md", "markdown", "csv", "tsv", "json", "jsonl", "xml", "html", "css",
  "js", "jsx", "ts", "tsx", "py", "rb", "go", "rs", "java", "c", "cpp", "h",
  "hpp", "toml", "yaml", "yml",
]);

const MIME_BY_EXTENSION: Record<string, string> = {
  pdf: "application/pdf",
  json: "application/json",
  jsonl: "application/x-ndjson",
  csv: "text/csv",
  tsv: "text/tab-separated-values",
  md: "text/markdown",
  markdown: "text/markdown",
  xml: "application/xml",
  html: "text/html",
  css: "text/css",
  js: "text/javascript",
  jsx: "text/javascript",
  ts: "text/typescript",
  tsx: "text/typescript",
  yaml: "application/yaml",
  yml: "application/yaml",
  toml: "application/toml",
};

export interface PickComposerAttachmentsOptions {
  kind: ChatAttachmentKind;
  remainingSlots: number;
}

function extensionOf(name: string): string {
  const index = name.lastIndexOf(".");
  return index < 0 ? "" : name.slice(index + 1).toLowerCase();
}

export function attachmentMimeType(name: string, reportedType: string): string {
  const normalized = reportedType.trim().toLowerCase();
  if (normalized && normalized !== "application/octet-stream") return normalized;
  return MIME_BY_EXTENSION[extensionOf(name)] ?? (TEXT_EXTENSIONS.has(extensionOf(name)) ? "text/plain" : normalized);
}

export function attachmentEncoding(attachment: Pick<ChatAttachment, "kind" | "name" | "mimeType">): "text" | "base64" {
  if (attachment.kind === "image" || attachment.mimeType === "application/pdf") return "base64";
  return "text";
}

export function validateComposerAttachment(
  file: Pick<File, "name" | "type" | "size">,
  requestedKind: ChatAttachmentKind,
): { kind: ChatAttachmentKind; mimeType: string } {
  const mimeType = attachmentMimeType(file.name, file.type);
  const extension = extensionOf(file.name);
  const isImage = mimeType.startsWith("image/");
  const isPdf = mimeType === "application/pdf" || extension === "pdf";
  const isText = mimeType.startsWith("text/")
    || TEXT_EXTENSIONS.has(extension)
    || mimeType === "application/json"
    || mimeType === "application/xml"
    || mimeType === "application/yaml"
    || mimeType === "application/toml"
    || mimeType === "application/x-ndjson";

  if (requestedKind === "image" && !isImage) {
    throw new Error(`${file.name} is not an image.`);
  }
  if (requestedKind === "document" && !isPdf && !isText) {
    throw new Error(`${file.name} is not a readable text or PDF document.`);
  }

  const maxBytes = isText && !isPdf ? MAX_TEXT_ATTACHMENT_BYTES : MAX_BINARY_ATTACHMENT_BYTES;
  if (!Number.isFinite(file.size) || file.size <= 0) {
    throw new Error(`${file.name} is empty or could not be read.`);
  }
  if (file.size > maxBytes) {
    const limit = Math.floor(maxBytes / (1024 * 1024));
    throw new Error(`${file.name} is too large. The limit is ${limit} MB.`);
  }

  return { kind: isImage ? "image" : "document", mimeType: isPdf ? "application/pdf" : mimeType };
}

function safeFileName(name: string): string {
  const compact = name.normalize("NFKC").replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
  return (compact || "attachment").slice(-120);
}

export async function pickComposerAttachments({
  kind,
  remainingSlots,
}: PickComposerAttachmentsOptions): Promise<ChatAttachment[]> {
  if (remainingSlots <= 0) throw new Error(`You can attach up to ${MAX_COMPOSER_ATTACHMENTS} files.`);
  const result = await File.pickFileAsync({
    multipleFiles: remainingSlots > 1,
    mimeTypes: kind === "image"
      ? "image/*"
      : ["text/*", "application/pdf", "application/json", "application/xml", "application/yaml"],
  });
  if (result.canceled) return [];
  const picked = Array.isArray(result.result) ? result.result : [result.result];
  if (picked.length > remainingSlots) {
    throw new Error(`Choose no more than ${remainingSlots} more attachment${remainingSlots === 1 ? "" : "s"}.`);
  }

  const validated = picked.map((file) => ({ file, ...validateComposerAttachment(file, kind) }));
  const directory = new Directory(Paths.document, "composer-attachments");
  directory.create({ idempotent: true, intermediates: true });

  const attachments: ChatAttachment[] = [];
  try {
    for (const entry of validated) {
      const id = createId("attachment");
      const destination = new File(directory, `${id}-${safeFileName(entry.file.name)}`);
      await entry.file.copy(destination);
      attachments.push({
        id,
        kind: entry.kind,
        name: entry.file.name,
        mimeType: entry.mimeType,
        size: entry.file.size,
        uri: destination.uri,
      });
    }
    return attachments;
  } catch (error) {
    for (const attachment of attachments) {
      const stored = new File(attachment.uri);
      if (stored.exists) stored.delete();
    }
    throw error;
  }
}

export async function hydrateMessageAttachments(attachments: readonly ChatAttachment[]): Promise<ChatAttachment[]> {
  return Promise.all(attachments.map(async (attachment) => {
    const file = new File(attachment.uri);
    if (!file.exists) throw new Error(`${attachment.name} is no longer available on this device. Remove it and attach it again.`);
    const encoding = attachmentEncoding(attachment);
    const data = encoding === "text" ? await file.text() : await file.base64();
    return { ...attachment, encoding, data };
  }));
}

export function removeComposerAttachmentFile(attachment: ChatAttachment): void {
  const file = new File(attachment.uri);
  if (file.exists) file.delete();
}

