  test("keeps bounded text and URI-only attachment metadata", () => {
    const draft = normalizeComposerDraft({
      text: "Compare these",
      attachments: [{
        id: "attachment-1",
        kind: "image",
        name: "diagram.png",
        mimeType: "image/png",
        size: 42,
        uri: "file:///documents/diagram.png",
        data: "must be dropped",
        encoding: "base64",
      }],
    });
    expect(draft.text).toBe("Compare these");
