  | "artifact"
  | "goal"
  | "question_check"
  | "quiz_result"
  | "deck"
  | "card_review"
  | "feedback_event"
  | "usage_event"
  | "topic_evidence";

export interface LocalAttachmentLocation {
  messageId: string;
  attachmentId: string;
  uri: string;
}

type LearnerRecord =
  | LearnerSession
  | LearnerArtifact
  | LearnerGoal
  | LearnerQuestionCheck
  | LearnerQuizResult
  | FlashcardDeck
  | CardReviewRecord
  | LearnerFeedbackEvent
